import { _decorator, Component, Label, Node } from 'cc';
import type { Bus } from '../../Engine/Bus';
import { BATTLE_EVENT } from '../../Battle/BattleEvents';
import type { CardConfigData } from '../../Battle/Config/CardConfig';

const { ccclass, property } = _decorator;

@ccclass('UpgradePanel')
export class UpgradePanel extends Component {

    @property(Node)
    rootNode: Node = null!;

    /** 三个卡牌按钮。每个按钮下有一个 Label 显示名字和描述 */
    @property([Node])
    cardNodes: Node[] = [];

    private _bus: Bus = null!;
    private _currentCards: CardConfigData[] = [];

    setup(bus: Bus): void {
        this._bus = bus;
        this._bus.on(BATTLE_EVENT.CARDS_DRAWN, this._onCardsDrawn, this);
    }

    onLoad() {
        this.rootNode.active = false;

        // 绑定每个卡牌按钮的点击
        for (let i = 0; i < this.cardNodes.length; i++) {
            const node = this.cardNodes[i];
            if (!node) continue;
            node.on(Node.EventType.TOUCH_END, () => this._onCardClick(i), this);
        }
    }

    onDestroy() {
        this._bus?.off(BATTLE_EVENT.CARDS_DRAWN, this._onCardsDrawn, this);
        for (const node of this.cardNodes) {
            if (node) node.off(Node.EventType.TOUCH_END);
        }
    }

    private _onCardsDrawn(cards: CardConfigData[]): void {
        this._currentCards = cards;
        this.rootNode.active = true;
        this._renderCards();
    }

    private _renderCards(): void {
        for (let i = 0; i < this.cardNodes.length; i++) {
            const node = this.cardNodes[i];
            const card = this._currentCards[i];

            if (!node) continue;

            if (!card) {
                node.active = false;
                continue;
            }

            node.active = true;
            const label = node.getChildByName('Label')?.getComponent(Label);
            if (label) {
                label.string = `${card.name}\n${card.desc}`;
            }
        }
    }

    private _onCardClick(index: number): void {
        const card = this._currentCards[index];
        if (!card) return;

        this.rootNode.active = false;
        this._currentCards = [];
        this._bus.emit(BATTLE_EVENT.CARD_SELECTED, card);
    }
}